<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Zaid Workspace</title>
    <meta name="description" content="Zaid workspace for planning tasks and schedules.">
    <style>
        :root { --ink:#2b193b; --muted:#756980; --line:#e8e1ee; --paper:#fff; --canvas:#f8f6fb; --lavender:#7151a8; --lavender-soft:#f0eafe; --lavender-pale:#faf7ff; --success:#2d8d68; --danger:#c54f62; }
        * { box-sizing:border-box } html { background:var(--canvas) } body { margin:0; background:var(--canvas); color:var(--ink); font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; -webkit-font-smoothing:antialiased } button,input,textarea { font:inherit } button { cursor:pointer } button:focus-visible,input:focus-visible,textarea:focus-visible { outline:3px solid #c9b6f2; outline-offset:2px }
        .skip { position:absolute;left:16px;top:-50px;background:var(--ink);color:#fff;padding:10px 14px;border-radius:8px;z-index:5 }.skip:focus { top:16px }.shell { min-height:100dvh;width:100%;background:var(--paper);box-shadow:0 0 0 1px var(--line) }
        .topbar { height:70px;display:flex;align-items:center;gap:24px;padding:0 28px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.94);position:sticky;top:0;z-index:2 }.logo { display:flex;align-items:center;gap:9px;color:var(--lavender);font-size:21px;font-weight:800;letter-spacing:-.055em;white-space:nowrap }.logo img { width:29px;height:29px;object-fit:contain }.main-nav { display:flex;gap:4px;height:100%;align-items:center }.main-nav a { display:grid;place-items:center;align-self:stretch;border-bottom:2px solid transparent;color:var(--muted);padding:0 14px;font-weight:650;text-decoration:none;transition:color .18s ease,border-color .18s ease }.main-nav a:hover { color:var(--ink) }.main-nav a.active { color:var(--lavender);border-color:var(--lavender) }.account { margin-left:auto;display:flex;align-items:center;gap:12px;color:var(--muted);font-size:12px }.avatar { display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:var(--lavender-soft);color:var(--lavender);font-weight:800 }.logout { border:1px solid var(--line);border-radius:9px;background:#fff;padding:8px 11px;color:var(--ink);font-weight:650;transition:background .18s ease,transform .12s ease }.logout:hover { background:var(--lavender-pale) }.logout:active,.primary:active,.icon-button:active { transform:scale(.96) }
        main { padding:28px }.view[hidden] { display:none }.workspace { display:grid;grid-template-columns:220px minmax(0,1fr);gap:28px }.rail { border-right:1px solid var(--line);padding-right:24px }.rail-label { color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;margin-bottom:12px }.mini-calendar { display:grid;grid-template-columns:repeat(7,1fr);gap:3px;font-variant-numeric:tabular-nums;margin-bottom:26px }.mini-calendar span { display:grid;place-items:center;height:25px;border-radius:50%;font-size:11px }.mini-calendar .mini-head { color:var(--muted);font-size:9px;font-weight:800 }.mini-calendar .mini-selected { background:var(--lavender);color:#fff;font-weight:800 }.rail-list { display:grid;gap:4px }.rail-list button { border:0;border-radius:8px;background:transparent;text-align:left;padding:9px 10px;color:var(--ink);font-weight:600 }.rail-list button:hover { background:var(--lavender-pale) }.rail-note { margin-top:30px;padding-top:20px;border-top:1px solid var(--line);color:var(--muted);font-size:12px;line-height:1.6 }
        .content-head { display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:24px }.eyebrow { color:var(--lavender);font-size:12px;font-weight:800;letter-spacing:.07em;text-transform:uppercase }.title { margin:3px 0 0;font-size:30px;line-height:1.1;letter-spacing:-.055em;text-wrap:balance }.subcopy { margin:7px 0 0;color:var(--muted) }.calendar-actions { display:flex;align-items:center;gap:8px }.view-filter { display:flex;align-items:center;gap:6px;min-height:40px;border:1px solid var(--line);border-radius:9px;padding:0 9px;color:var(--muted);font-size:12px;font-weight:700 }.view-filter select { border:0;background:#fff;color:var(--ink);font:inherit;font-weight:700;outline:0 }.icon-button,.secondary,.primary { min-height:40px;border-radius:9px;padding:0 13px;font-weight:700;transition:background .18s ease,transform .12s ease }.icon-button,.secondary { border:1px solid var(--line);background:#fff;color:var(--ink) }.icon-button:hover,.secondary:hover { background:var(--lavender-pale) }.arrow-button { display:grid;place-items:center;width:40px;padding:0 }.arrow-button svg { width:18px;height:18px;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round;stroke-width:2.1 }.primary { border:1px solid var(--lavender);background:var(--lavender);color:#fff;box-shadow:0 5px 13px rgba(113,81,168,.18) }.primary:hover { background:#60438f }.calendar-layout { display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:22px }.calendar-panel,.task-group,.ai-card { background:#fff;border:1px solid var(--line);border-radius:16px }.calendar-panel { overflow:hidden }.weekdays,.calendar-grid { display:grid;grid-template-columns:repeat(7,minmax(0,1fr)) }.weekdays { border-bottom:1px solid var(--line);background:#fcfbfd }.weekdays div { padding:11px 8px;text-align:right;color:var(--muted);font-size:11px;font-weight:800;text-transform:uppercase }.day { min-height:112px;border:0;border-right:1px solid var(--line);border-bottom:1px solid var(--line);background:#fff;padding:9px;text-align:left;vertical-align:top;color:var(--ink);transition:background .18s ease,box-shadow .18s ease }.week-grid { display:grid;grid-template-columns:50px repeat(7,minmax(0,1fr));grid-template-rows:repeat(13,48px);max-height:calc(100dvh - 260px);min-height:580px;overflow:auto;background:#fff }.week-time,.week-cell { border-right:1px solid var(--line);border-bottom:1px solid var(--line) }.week-time { padding:6px 8px 0 0;color:var(--muted);font-size:10px;text-align:right }.week-cell { position:relative;background:#fff }.week-event { position:absolute;inset:5px 5px auto;border:0;border-left:3px solid var(--lavender);border-radius:5px;background:var(--lavender-soft);padding:5px 7px;color:#50377d;font-size:11px;font-weight:700;text-align:left;overflow:hidden;white-space:nowrap;text-overflow:ellipsis }.week-day { display:grid;place-items:center;border-right:1px solid var(--line);border-bottom:1px solid var(--line);color:var(--muted);font-size:11px;font-weight:800;text-transform:uppercase }.week-day strong { display:block;color:var(--ink);font-size:18px;line-height:1.2 }.week-day.today strong { display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--lavender);color:#fff }.day:nth-child(7n) { border-right:0 }.day:hover { background:var(--lavender-pale) }.day.outside { color:#c5bdca;background:#fdfcff }.day.selected { background:#faf7ff;box-shadow:inset 0 0 0 2px var(--lavender) }.day.today .day-number { background:var(--lavender);color:#fff }.day-number { display:grid;place-items:center;width:27px;height:27px;border-radius:50%;font-variant-numeric:tabular-nums;font-weight:700 }.event-pill { display:block;width:100%;margin-top:12px;overflow:hidden;border-left:3px solid var(--lavender);border-radius:4px;background:var(--lavender-soft);padding:4px 6px;color:#50377d;font-size:11px;font-weight:700;white-space:nowrap;text-overflow:ellipsis }.more { margin-top:4px;color:var(--lavender);font-size:11px;font-weight:700 }
        .panel-head { display:flex;align-items:flex-start;justify-content:space-between;gap:10px;padding-bottom:14px;border-bottom:1px solid var(--line) }.panel-head strong { font-size:16px;letter-spacing:-.025em }.date-copy { margin-top:2px;color:var(--muted);font-size:12px }.agenda-items { display:grid;gap:8px;max-height:390px;overflow:auto;padding-top:14px }.agenda-item { display:flex;gap:10px;align-items:flex-start;border:1px solid var(--line);border-radius:10px;padding:10px;transition:background .18s ease,box-shadow .18s ease }.agenda-item:hover { background:var(--lavender-pale);box-shadow:0 4px 12px rgba(62,38,88,.06) }.check { appearance:none;flex:0 0 17px;width:17px;height:17px;margin:2px 0 0;border:1.5px solid #b7a9c2;border-radius:5px;background:#fff;cursor:pointer }.check:checked { border-color:var(--lavender);background:var(--lavender) }.check:checked::after { content:'✓';display:block;color:#fff;font-size:12px;line-height:15px;text-align:center }.agenda-main { min-width:0;flex:1;border:0;background:transparent;text-align:left;padding:0;color:inherit }.agenda-title { overflow:hidden;font-weight:700;white-space:nowrap;text-overflow:ellipsis }.agenda-meta { color:var(--muted);font-size:11px;margin-top:2px }.empty { color:var(--muted);padding:22px 0;text-align:center }.ai-card { height:100%;min-height:480px;padding:22px;background:linear-gradient(145deg,#fff 0%,#faf7ff 100%) }.ai-card h2 { margin:0;font-size:18px;letter-spacing:-.035em }.ai-card p { margin:6px 0 16px;color:var(--muted);font-size:13px }.ai-card textarea { width:100%;min-height:220px;border:1px solid var(--line);border-radius:11px;background:#fff;padding:12px;color:var(--ink);resize:vertical }.ai-actions { display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:12px }.status { color:var(--muted);font-size:11px }.status.error { color:var(--danger) }.status.success { color:var(--success) }.confirmation { margin-top:10px;border-left:3px solid var(--lavender);background:var(--lavender-soft);padding:9px;color:#4e3876;font-size:12px }.confirmation button { margin:8px 5px 0 0;border:0;border-radius:7px;padding:6px 8px;background:var(--lavender);color:#fff;font-weight:700 }.confirmation button:last-child { background:transparent;color:#4e3876;text-decoration:underline }.agenda-modal { width:min(520px,100%);max-height:min(80dvh,650px);overflow:auto }
        .tasks-head { display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:24px }.task-tools { display:flex;gap:8px }.task-board { display:grid;grid-template-columns:repeat(3,minmax(220px,1fr));gap:16px;align-items:start;overflow:auto;padding-bottom:8px }.task-group { min-height:280px;padding:15px }.task-group-head { display:flex;align-items:center;justify-content:space-between;padding-bottom:11px;border-bottom:1px solid var(--line) }.task-group-head h2 { margin:0;font-size:15px;letter-spacing:-.02em }.task-count { color:var(--muted);font-variant-numeric:tabular-nums;font-size:12px }.add-task-link { display:block;width:100%;border:0;background:transparent;padding:12px 0 5px;text-align:left;color:var(--lavender);font-weight:700 }.add-task-link:hover { text-decoration:underline }.task-list { display:grid;gap:7px }.task-card { display:flex;gap:9px;align-items:flex-start;padding:10px 0;border-bottom:1px solid #f0edf3 }.task-card:last-child { border-bottom:0 }.task-card .agenda-main { padding-top:0 }.task-card.completed .agenda-title { color:var(--muted);text-decoration:line-through }.task-card .check:checked { background:var(--success);border-color:var(--success) }
        .modal { position:fixed;inset:0;z-index:4;display:grid;place-items:center;padding:18px;background:rgba(48,29,67,.25);backdrop-filter:blur(3px) }.modal[hidden] { display:none }.modal-card { width:min(500px,100%);border-radius:17px;background:#fff;padding:22px;box-shadow:0 22px 70px rgba(47,28,65,.24) }.modal-card h2 { margin:0;font-size:20px;letter-spacing:-.04em }.field { display:grid;gap:5px;margin:13px 0;color:var(--muted);font-size:12px;font-weight:650 }.field input,.field textarea { width:100%;border:1px solid var(--line);border-radius:9px;background:#fff;padding:10px;color:var(--ink);resize:vertical }.two { display:grid;grid-template-columns:1fr 1fr;gap:11px }.modal-actions { display:flex;justify-content:flex-end;gap:8px;margin-top:17px }.danger { margin-right:auto;border:0;background:transparent;color:var(--danger);font-weight:700 }.danger:hover { text-decoration:underline }
        @media(max-width:1050px){.workspace{grid-template-columns:1fr}.rail{display:none}.calendar-layout{grid-template-columns:minmax(0,1fr) 275px}.week-grid{max-height:600px}} @media(max-width:760px){.topbar{height:auto;min-height:64px;padding:0 16px;gap:8px;flex-wrap:wrap}.main-nav{order:3;width:100%;height:44px}.main-nav a{flex:1}.account{margin-left:auto}.account .email{display:none}main{padding:16px}.calendar-layout{grid-template-columns:1fr}.day{min-height:76px;padding:6px}.weekdays div{font-size:9px;padding:8px 3px}.event-pill{margin-top:5px}.agenda-panel{min-height:auto}.task-board{grid-template-columns:minmax(260px,1fr) minmax(260px,1fr) minmax(260px,1fr)}.title{font-size:25px}.content-head,.tasks-head{align-items:flex-start;flex-direction:column}.calendar-actions,.task-tools{width:100%}.calendar-actions .primary,.task-tools .primary{margin-left:auto}.account{font-size:0}.logout{font-size:12px}.two{grid-template-columns:1fr}}
        @media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition:none!important}}
    </style>
</head>
<body>
<a class="skip" href="#main">Skip to workspace</a>
<div class="shell">
    <header class="topbar">
        <div class="logo"><img src="/images/brand/zaid-logo.png" alt="">Zaid Workspace</div>
        <nav class="main-nav" aria-label="Primary navigation"><a class="{{ $initialView === 'calendar' ? 'active' : '' }}" href="/dashboard">Calendar</a><a class="{{ $initialView === 'tasks' ? 'active' : '' }}" href="/dashboard/tasks">Tasks</a></nav>
        <div class="account"><span class="email" id="profile-email">Loading…</span><span class="avatar" id="profile-initial">Z</span><button class="logout" type="button" id="logout">Logout</button></div>
    </header>
    <main id="main">
        <section class="view" id="calendar-view" aria-label="Calendar view" @if ($initialView !== 'calendar') hidden @endif>
            <div class="workspace">
                <aside class="rail" aria-label="Calendar sidebar"><div class="rail-label">This month</div><div class="mini-calendar" id="mini-calendar"></div><div class="rail-list"><button type="button" id="today-nav">Today</button><button type="button" id="tasks-nav">View all tasks</button></div><p class="rail-note">Your tasks and schedule live in Zaid. Google is used only for sign-in.</p></aside>
                <section>
                    <div class="content-head"><div><div class="eyebrow">Planning</div><h1 class="title" id="month-title">Calendar</h1><p class="subcopy">Click any date to view and manage its agenda.</p></div><div class="calendar-actions"><button class="icon-button arrow-button" type="button" id="previous-month" aria-label="Previous period"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14.5 5-7 7 7 7"/></svg></button><button class="secondary" type="button" id="today">Today</button><button class="icon-button arrow-button" type="button" id="next-month" aria-label="Next period"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9.5 5 7 7-7 7"/></svg></button><label class="view-filter"><select id="calendar-mode" aria-label="Calendar view"><option value="month">Month</option><option value="week">Week</option></select></label><button class="primary" type="button" id="new-task">+ New task</button></div></div>
                    <div class="calendar-layout"><section class="calendar-panel" aria-label="Calendar"><div class="weekdays" id="weekdays"><div>Sun</div><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div></div><div class="calendar-grid" id="calendar-grid" role="grid"></div><div class="week-grid" id="week-grid" hidden></div></section><aside class="ai-card" aria-label="Ask Zaid"><h2>Ask Zaid</h2><p>Plan, reschedule, or create tasks in natural language.</p><textarea id="prompt" placeholder="Besok jam 10 follow up client 30 menit"></textarea><div id="confirmation" class="confirmation" hidden></div><div class="ai-actions"><span class="status" id="status" role="status" aria-live="polite"></span><button class="primary" type="button" id="ask">Ask Zaid</button></div></aside></div>
                </section>
            </div>
        </section>
        <section class="view" id="tasks-view" aria-label="Tasks view" @if ($initialView !== 'tasks') hidden @endif>
            <div class="tasks-head"><div><div class="eyebrow">Work list</div><h1 class="title">My tasks</h1><p class="subcopy">Organize work in your own lists.</p></div><div class="task-tools"><label class="view-filter">Show <select id="task-filter"><option value="all">All</option><option value="today">Today</option><option value="upcoming">Upcoming</option></select></label><button class="secondary" type="button" id="new-list">+ New list</button><button class="primary" type="button" id="tasks-add">+ Add task</button></div></div>
            <div class="task-board" id="task-board"></div>
        </section>
    </main>
</div>
<div class="modal" id="date-action-modal" hidden><section class="modal-card"><h2>Add to calendar</h2><p class="subcopy">Choose what you want to create on this date.</p><div class="modal-actions"><button class="secondary" type="button" id="create-task-from-date">Task</button><button class="primary" type="button" id="create-event-from-date">Event</button></div></section></div>
<div class="modal" id="event-modal" hidden><form class="modal-card" id="event-form"><h2 id="event-form-title">New event</h2><input id="event-id" type="hidden"><label class="field">Event title<input id="event-title" required maxlength="255"></label><label class="field">Notes<textarea id="event-description" rows="3"></textarea></label><div class="two"><label class="field">Starts<input id="event-start" type="datetime-local" required></label><label class="field">Ends<input id="event-end" type="datetime-local"></label></div><label class="field"><span><input id="event-all-day" type="checkbox"> All day</span></label><div class="modal-actions"><button class="danger" type="button" id="delete-event" hidden>Delete event</button><button class="secondary" type="button" id="cancel-event">Cancel</button><button class="primary" type="submit">Save event</button></div></form></div>
<div class="modal" id="task-modal" hidden><form class="modal-card" id="task-form"><h2 id="form-title">New task</h2><input id="task-id" type="hidden"><label class="field">Task title<input id="task-title" required maxlength="255"></label><label class="field">Notes<textarea id="task-description" rows="3"></textarea></label><div class="two"><label class="field">Date<input id="task-date" type="date"></label><label class="field">Time<input id="task-time" type="time"></label></div><label class="field">List<select id="task-list-id"></select></label><label class="field"><span><input id="task-all-day" type="checkbox"> All day</span></label><div class="modal-actions"><button class="danger" type="button" id="delete-task" hidden>Delete task</button><button class="secondary" type="button" id="cancel-task">Cancel</button><button class="primary" type="submit">Save task</button></div></form></div>
<div class="modal" id="list-modal" hidden><form class="modal-card" id="list-form"><h2>New list</h2><p class="subcopy">Group related tasks in one place.</p><label class="field">List name<input id="list-name" required maxlength="100" autocomplete="off" placeholder="e.g. Work"></label><div class="modal-actions"><button class="secondary" type="button" id="cancel-list">Cancel</button><button class="primary" type="submit">Create list</button></div></form></div>
<script>
const initialView = @json($initialView);
const tokenKey='zaid_web_access_token',verificationKey='zaid_verification_id',phoneKey='zaid_phone_number';
const state={visibleMonth:new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedDate:new Date().toISOString().slice(0,10),monthDays:new Map(),events:[],allTasks:[],taskLists:[],pendingPrompt:null,view:initialView,calendarMode:'month',taskFilter:'all'};
const $=id=>document.getElementById(id);
const pad=n=>String(n).padStart(2,'0');
function dateKey(date){return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}`} function monthKey(date){return dateKey(date).slice(0,7)}
function clearSession(){[tokenKey,verificationKey,phoneKey].forEach(key=>localStorage.removeItem(key))}
function setText(id,text){$(id).textContent=text||''} function status(message,type=''){const node=$('status');node.textContent=message||'';node.className=`status ${type}`}
async function api(path,options={}){const response=await fetch('/api/v1'+path,{...options,headers:{Accept:'application/json',Authorization:`Bearer ${localStorage.getItem(tokenKey)}`,...(options.headers||{})}});const data=await response.json().catch(()=>({message:'Unexpected server response'}));if(!response.ok)throw data;return data}
function showView(name){window.location.assign(name==='tasks'?'/dashboard/tasks':'/dashboard')}
async function boot(){if(!localStorage.getItem(tokenKey)){location.replace('/app');return}try{const [onboarding,me]=await Promise.all([api('/onboarding/status'),api('/me')]);if(onboarding.data.next_step!=='dashboard'){location.replace('/app');return}setText('profile-email',me.data.email);setText('profile-initial',(me.data.full_name||me.data.email||'Z').slice(0,1).toUpperCase())}catch(error){clearSession();location.replace('/app');return}await Promise.all([loadMonth(),loadTasks(),loadTaskLists()].map(request=>request.catch(error=>status(error.message||'Could not load workspace.','error'))))}
async function refresh(){await Promise.all([loadMonth(),loadTasks(),loadTaskLists()])}
async function loadMonth(){const start=new Date(state.visibleMonth.getFullYear(),state.visibleMonth.getMonth(),1);const end=new Date(state.visibleMonth.getFullYear(),state.visibleMonth.getMonth()+1,0);try{const data=await api(`/events?from=${dateKey(start)}&to=${dateKey(end)}`);state.events=data.data.items||[]}catch(error){state.events=[];status(error.message||'Could not load events.','error')}renderCalendar();renderMiniCalendar()}
function renderCalendar(){const isWeek=state.calendarMode==='week';$('calendar-grid').hidden=isWeek;$('weekdays').hidden=isWeek;$('week-grid').hidden=!isWeek;setText('month-title',state.visibleMonth.toLocaleDateString(undefined,{month:'long',year:'numeric'}));if(isWeek){renderWeek();return}const grid=$('calendar-grid');grid.replaceChildren();const first=new Date(state.visibleMonth.getFullYear(),state.visibleMonth.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());const today=dateKey(new Date());for(let i=0;i<42;i++){const day=new Date(start);day.setDate(start.getDate()+i);const key=dateKey(day),summary=state.monthDays.get(key),button=document.createElement('button');button.type='button';button.className=`day${day.getMonth()!==state.visibleMonth.getMonth()?' outside':''}${key===state.selectedDate?' selected':''}${key===today?' today':''}`;button.setAttribute('aria-label',`${day.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}${summary?.task_count?`, ${summary.task_count} tasks`:''}`);const number=document.createElement('span');number.className='day-number';number.textContent=day.getDate();button.append(number);const events=state.events.filter(event=>event.starts_at?.slice(0,10)===key);events.slice(0,2).forEach(event=>{const pill=document.createElement('span');pill.className='event-pill';pill.textContent=event.title;button.append(pill)});if(events.length>2){const more=document.createElement('span');more.className='more';more.textContent=`+${events.length-2} more`;button.append(more)}button.onclick=()=>selectDate(key);grid.append(button)}}
function renderWeek(){const grid=$('week-grid');grid.replaceChildren();const selected=new Date(`${state.selectedDate}T00:00:00`),start=new Date(selected);start.setDate(selected.getDate()-selected.getDay());const blank=document.createElement('div');blank.className='week-day';grid.append(blank);const today=dateKey(new Date());const days=[];for(let col=0;col<7;col++){const day=new Date(start);day.setDate(start.getDate()+col);days.push(day);const head=document.createElement('div');head.className=`week-day${dateKey(day)===today?' today':''}`;head.innerHTML=`${day.toLocaleDateString(undefined,{weekday:'short'})}<strong>${day.getDate()}</strong>`;grid.append(head)}for(let hour=8;hour<=19;hour++){const label=document.createElement('div');label.className='week-time';label.textContent=`${String(hour).padStart(2,'0')}:00`;grid.append(label);days.forEach(day=>{const cell=document.createElement('button');cell.type='button';cell.className='week-cell';const key=dateKey(day);cell.onclick=()=>selectDate(key);state.events.filter(event=>event.starts_at?.slice(0,10)===key).filter(event=>event.all_day||Number(event.starts_at.slice(11,13))===hour).forEach(event=>{const item=document.createElement('span');item.className='week-event';item.textContent=`${event.all_day?'All day':event.starts_at.slice(11,16)} ${event.title}`;cell.append(item)});grid.append(cell)})}}
function renderMiniCalendar(){const box=$('mini-calendar');box.replaceChildren();['S','M','T','W','T','F','S'].forEach(label=>{const item=document.createElement('span');item.className='mini-head';item.textContent=label;box.append(item)});const first=new Date(state.visibleMonth.getFullYear(),state.visibleMonth.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());for(let i=0;i<42;i++){const day=new Date(start);day.setDate(start.getDate()+i);const item=document.createElement('span');item.textContent=day.getDate();if(dateKey(day)===state.selectedDate)item.className='mini-selected';box.append(item)}}
async function selectDate(date){state.selectedDate=date;state.visibleMonth=new Date(`${date}T00:00:00`);await loadMonth();$('date-action-modal').hidden=false}
function taskTime(task){return task.all_day?'All day':(task.scheduled_time||'No time').slice(0,5)}
async function loadAgenda(){const data=await api(`/agenda/day?date=${state.selectedDate}`);const items=data.data.items||[];setText('agenda-title',`Agenda · ${items.length}`);setText('agenda-date',new Date(`${state.selectedDate}T00:00:00`).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}));const box=$('agenda-items');box.replaceChildren();if(!items.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='Nothing scheduled for this date.';box.append(empty);return}items.forEach(task=>box.append(taskRow(task,'agenda-item')))}
async function loadTasks(){try{const data=await api('/tasks?include_completed=false');const completed=await api('/tasks?status=completed');state.allTasks=[...(data.data.items||[]),...(completed.data.items||[])]}catch(error){state.allTasks=[];status(error.message||'Could not load tasks.','error')}renderTaskBoard()}
async function loadTaskLists(){try{const data=await api('/task-lists');state.taskLists=data.data.items||[]}catch(error){state.taskLists=[];status(error.message||'Could not load lists.','error')}renderTaskBoard()}
function taskRow(task,className){const card=document.createElement('article');card.className=`${className}${task.status==='completed'?' completed':''}`;const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.className='check';checkbox.checked=task.status==='completed';checkbox.setAttribute('aria-label',`Complete ${task.title}`);checkbox.onchange=async()=>{try{if(task.status==='completed')return;await api(`/tasks/${task.id}/complete`,{method:'POST'});status('Task completed.','success');await refresh()}catch(error){checkbox.checked=false;status(error.message||'Could not complete task.','error')}};const body=document.createElement('button');body.type='button';body.className='agenda-main';const title=document.createElement('div');title.className='agenda-title';title.textContent=task.title;const meta=document.createElement('div');meta.className='agenda-meta';meta.textContent=task.scheduled_date?`${task.scheduled_date} · ${taskTime(task)}`:taskTime(task);body.append(title,meta);body.onclick=()=>openTask(task);card.append(checkbox,body);return card}
function renderTaskBoard(){const board=$('task-board');if(!board)return;board.replaceChildren();const visible=state.allTasks.filter(task=>state.taskFilter==='all'||(state.taskFilter==='today'?task.scheduled_date===dateKey(new Date()):task.scheduled_date>=dateKey(new Date())));const lists=state.taskLists.length?state.taskLists:[{id:null,name:'My Tasks'}];lists.forEach(list=>{const column=document.createElement('section');column.className='task-group';const head=document.createElement('div');head.className='task-group-head';const title=document.createElement('h2');title.textContent=list.name;const count=document.createElement('span');count.className='task-count';const items=visible.filter(task=>task.task_list_id===list.id);count.textContent=items.length;head.append(title,count);const add=document.createElement('button');add.className='add-task-link';add.textContent='+ Add a task';add.onclick=()=>openTask(null,list.id);const body=document.createElement('div');body.className='task-list';items.forEach(task=>body.append(taskRow(task,'task-card')));column.append(head,add,body);board.append(column)})}
function fillTaskLists(selected=null){const select=$('task-list-id');select.replaceChildren();state.taskLists.forEach(list=>{const option=document.createElement('option');option.value=list.id;option.textContent=list.name;option.selected=list.id===selected;select.append(option)})}
function openTask(task=null,listId=null){$('task-form').reset();$('task-id').value=task?.id||'';setText('form-title',task?'Edit task':'New task');$('task-title').value=task?.title||'';$('task-description').value=task?.description||'';$('task-date').value=task?.scheduled_date||state.selectedDate;$('task-time').value=(task?.scheduled_time||'').slice(0,5);$('task-all-day').checked=!!task?.all_day;fillTaskLists(task?.task_list_id||listId);$('delete-task').hidden=!task;$('task-modal').hidden=false}
function closeTask(){$('task-modal').hidden=true}
function openList(){$('list-form').reset();$('list-modal').hidden=false;$('list-name').focus()}
function closeList(){$('list-modal').hidden=true}
async function saveList(event){event.preventDefault();const name=$('list-name').value.trim();if(!name)return;try{await api('/task-lists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});closeList();await loadTaskLists()}catch(error){status(error.message||'Could not create list.','error')}}
function openEvent(event=null){$('event-form').reset();$('event-id').value=event?.id||'';setText('event-form-title',event?'Edit event':'New event');$('event-title').value=event?.title||'';$('event-description').value=event?.description||'';const start=event?.starts_at?event.starts_at.slice(0,16):`${state.selectedDate}T09:00`;$('event-start').value=start;$('event-end').value=event?.ends_at?.slice(0,16)||'';$('event-all-day').checked=!!event?.all_day;$('delete-event').hidden=!event;$('event-modal').hidden=false}
async function saveEvent(event){event.preventDefault();const id=$('event-id').value,payload={title:$('event-title').value.trim(),description:$('event-description').value.trim()||null,starts_at:$('event-start').value,ends_at:$('event-end').value||null,all_day:$('event-all-day').checked,timezone:'Asia/Jakarta'};try{await api(id?`/events/${id}`:'/events',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('event-modal').hidden=true;status('Event saved.','success');await loadMonth()}catch(error){status(error.message||'Could not save event.','error')}}
async function deleteEvent(){const id=$('event-id').value;if(!id||!window.confirm('Delete this event?'))return;await api(`/events/${id}`,{method:'DELETE'});$('event-modal').hidden=true;await loadMonth()}
async function saveTask(event){event.preventDefault();const id=$('task-id').value,allDay=$('task-all-day').checked,payload={title:$('task-title').value.trim(),description:$('task-description').value.trim()||null,task_list_id:$('task-list-id').value||null,scheduled_date:$('task-date').value||null,scheduled_time:allDay?null:($('task-time').value?`${$('task-time').value}:00`:null),timezone:'Asia/Jakarta',all_day:allDay};try{await api(id?`/tasks/${id}`:'/tasks',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});closeTask();status('Task saved.','success');await refresh()}catch(error){status(error.message||'Could not save task.','error')}}
async function deleteTask(){const id=$('task-id').value;if(!id||!window.confirm('Delete this task?'))return;try{await api(`/tasks/${id}`,{method:'DELETE'});closeTask();status('Task deleted.','success');await refresh()}catch(error){status(error.message||'Could not delete task.','error')}}
function renderConfirmation(data){const box=$('confirmation');box.replaceChildren();const question=document.createElement('div');question.textContent=data.confirmation?.question||'Confirm this action?';const yes=document.createElement('button');yes.textContent='Confirm';yes.onclick=()=>confirmPrompt(true);const no=document.createElement('button');no.textContent='Cancel';no.onclick=()=>confirmPrompt(false);box.append(question,yes,no);box.hidden=false}
async function ask(){const text=$('prompt').value.trim();if(!text)return;const button=$('ask');button.disabled=true;try{const data=await api('/prompts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})});if(data.data.requires_confirmation){state.pendingPrompt=data.data.prompt_request_id;renderConfirmation(data.data);status(data.data.human_response||'Confirmation required.');return}$('prompt').value='';status(data.data.human_response||data.message,'success');await refresh()}catch(error){status(error.message||'Could not process prompt.','error')}finally{button.disabled=false}}
async function confirmPrompt(confirmed){if(!state.pendingPrompt)return;try{const data=await api(`/prompts/${state.pendingPrompt}/confirm`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed})});state.pendingPrompt=null;$('confirmation').hidden=true;$('prompt').value='';status(data.data.human_response||'Prompt updated.','success');if(confirmed)await refresh()}catch(error){status(error.message||'Could not confirm prompt.','error')}}
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>showView(button.dataset.view));document.querySelectorAll('[data-add-task]').forEach(button=>button.onclick=()=>openTask());$('new-task').onclick=()=>openEvent();$('create-task-from-date').onclick=()=>{ $('date-action-modal').hidden=true;openTask()};$('create-event-from-date').onclick=()=>{ $('date-action-modal').hidden=true;openEvent()};$('tasks-add').onclick=()=>openTask();$('new-list').onclick=openList;$('list-form').onsubmit=saveList;$('cancel-list').onclick=closeList;$('task-filter').onchange=event=>{state.taskFilter=event.target.value;renderTaskBoard()};$('calendar-mode').onchange=event=>{state.calendarMode=event.target.value;renderCalendar()};$('previous-month').onclick=async()=>{if(state.calendarMode==='week'){const date=new Date(`${state.selectedDate}T00:00:00`);date.setDate(date.getDate()-7);state.selectedDate=dateKey(date);state.visibleMonth=new Date(date.getFullYear(),date.getMonth(),1)}else state.visibleMonth.setMonth(state.visibleMonth.getMonth()-1);await loadMonth()};$('next-month').onclick=async()=>{if(state.calendarMode==='week'){const date=new Date(`${state.selectedDate}T00:00:00`);date.setDate(date.getDate()+7);state.selectedDate=dateKey(date);state.visibleMonth=new Date(date.getFullYear(),date.getMonth(),1)}else state.visibleMonth.setMonth(state.visibleMonth.getMonth()+1);await loadMonth()};$('today').onclick=async()=>selectDate(dateKey(new Date()));$('today-nav').onclick=async()=>selectDate(dateKey(new Date()));$('tasks-nav').onclick=()=>showView('tasks');$('ask').onclick=ask;$('task-form').onsubmit=saveTask;$('cancel-task').onclick=closeTask;$('delete-task').onclick=deleteTask;$('event-form').onsubmit=saveEvent;$('cancel-event').onclick=()=>{$('event-modal').hidden=true};$('delete-event').onclick=deleteEvent;$('logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST'})}catch(error){}clearSession();location.replace('/app')};boot();
</script>
</body>
</html>
